import{_ as s,o as a,c as n,ag as p}from"./chunks/framework.CD3EN-rd.js";const i=JSON.parse('{"title":"第2章  建设工程项目管理相关体系标准","description":"","frontmatter":{"title":"第2章  建设工程项目管理相关体系标准","layout":"doc","order":3},"headers":[],"relativePath":"考试/一级建造师/工程管理/第2章  建设工程项目管理相关体系标准.md","filePath":"考试/一级建造师/工程管理/第2章  建设工程项目管理相关体系标准.md","lastUpdated":1767119520000}'),l={name:"考试/一级建造师/工程管理/第2章  建设工程项目管理相关体系标准.md"};function e(r,t,d,c,o,y){return a(),n("div",null,[...t[0]||(t[0]=[p('<h1 id="第2章-建设工程项目管理相关体系标准" tabindex="-1">第2章  建设工程项目管理相关体系标准 <a class="header-anchor" href="#第2章-建设工程项目管理相关体系标准" aria-label="Permalink to &quot;第2章  建设工程项目管理相关体系标准&quot;">​</a></h1><h2 id="_2-1-质量、环境、职业健康安全管理体系" tabindex="-1">2.1  质量、环境、职业健康安全管理体系 <a class="header-anchor" href="#_2-1-质量、环境、职业健康安全管理体系" aria-label="Permalink to &quot;2.1  质量、环境、职业健康安全管理体系&quot;">​</a></h2><p><strong>【考点概括】</strong></p><p><img src="https://tupian-d290.obs.cn-east-3.myhuaweicloud.com/img/1762607359463.png" alt="" loading="lazy"></p><h3 id="_2-1-1-质量管理体系" tabindex="-1">2.1.1 质量管理体系 <a class="header-anchor" href="#_2-1-1-质量管理体系" aria-label="Permalink to &quot;2.1.1 质量管理体系&quot;">​</a></h3><p><strong>【考点】质量管理体系</strong></p><p><strong>【考点概括】</strong></p><p>1.质量管理体系标准结构及关键要素（重要）</p><p>2.质量管理基本原则和核心（必会）</p><p><strong>1.质量管理体系标准结构及关键要素</strong></p><p>1）质量管理体系结构（重要）</p><p><img src="https://tupian-d290.obs.cn-east-3.myhuaweicloud.com/img/1762607380674.png" alt="" loading="lazy"></p><p>2）质量管理体系关键要素（重要）</p><p><strong>【课中知识拓展】质量管理体系是指由组织机构、过程、程序和资源组成的有机整体，以保证产品和服务质量满足规定（或隐含）的要求。</strong></p><table><tbody><tr><td>（1）组织机构</td><td colspan="2"> 组织对人员职责、权限和相互关系的有序安排，包括与外部组织的有关接口</td></tr><tr style="text-align:left;"><td rowspan="3"><span class="font-jcysxh">（2）过程<br> 相互关联<br> 相互作用<br> 一组活动<br><br><br><br><br> 顾客支持管理</span></td><td> ①顾客导向<br> 过程 </td><td> 通过输入和输出直接与外部顾客联系的过程。<br> 【帮助理解】直接和顾客打交道的事。<br> 【内容】了解顾客需求、开发产品、为生产服务提供控制、产品交<br> 付后的防护 </td></tr><tr style="text-align:left;"><td> ②支持过程 </td><td> 提供主要资源或能力，支持顾客导向过程实现预计质量目标的过程。<br> 【帮助理解】为顾客导向过程提供“后勤保障”。<br> 【内容】提供资源（设备、环境、知识、信息等）、运行策划过程、<br> 外部供应产品的控制、标识和可追溯性、不合格产品和服务等。 </td></tr><tr style="text-align:left;"><td> ③管理过程 </td><td> 用来衡量和评价顾客导向过程和支持过程的有效性和效率<br> 【帮助理解】监督和改进整个体系，确保高效运行。<br> 【内容】制定目标、评估风险、分析数据、顾客满意、内部审核、<br> 管理评审、持续改进、纠偏等。 </td></tr><tr style="text-align:left;"><td rowspan="3"> （3）程序 </td><td colspan="2"> 为进行某项活动所<span class="font-jcysxh">规定的途径</span>。程序可<span class="font-jcysxh">形成文件</span>，也可<span class="font-jcysxh">不形成文件</span></td></tr><tr style="text-align:left;"><td colspan="2"> ①要求<span class="font-jcysxh">保持</span>的成文信息。包括：质量管理体系的范围、质量方针、质量目标 </td></tr><tr style="text-align:left;"><td colspan="2"> ②要求<span class="font-jcysxh">保留</span>的成文信息。包括：各种证据（可追溯性的唯一性标识） </td></tr><tr style="text-align:left;"><td> （4）资源 </td><td colspan="2"> 组织拥有的<span class="font-jcysxh">物力、财力、人力、智力</span>（信息、知识）等各种物质要素的总称 </td></tr></tbody></table><p><strong>【口诀】“祖国橙子”、“顾客支持管理”的过程</strong></p><p>2.质量管理基本原则和核心（必会）</p><p>质量管理原则是质量管理体系标准的<span class="font-jcys">编制基础</span>。《质量管理体系基础和术语》GB/T19000—2016</p><p>提出了质量管理 7 项原则：</p><p>①以<span class="font-jcys">顾客</span>为关注焦点；</p><p>②<span class="font-jcys">领导</span>作用；</p><p>③<span class="font-jcys">全员</span>积极参与；</p><p>④<span class="font-jcys">过程</span>方法；</p><p>⑤<span class="font-jcys">改进</span>；</p><p>⑥<span class="font-jcys">循证</span>决策；</p><p>⑦<span class="font-jcys">关系</span>管理。</p><p>【口诀】“遵循顾客和领导的关系，全程改”，其中“全程改”属于质量管理核心。</p><p><strong>【课中知识拓展】循证决策：基于数据和信息的分析和评价的决策，更有可能产生期望的结果。</strong></p><p><strong>【考点总结】</strong></p><p><img src="https://tupian-d290.obs.cn-east-3.myhuaweicloud.com/img/1762608834821.png" alt="" loading="lazy"></p><h3 id="_2-1-2-环境管理体系" tabindex="-1">2.1.2 环境管理体系 <a class="header-anchor" href="#_2-1-2-环境管理体系" aria-label="Permalink to &quot;2.1.2 环境管理体系&quot;">​</a></h3><p>【考点】环境管理体系</p><p>【考点概括】</p><p>1.环境管理体系标准分类（重要）</p><p>2.环境管理体系的基本理念和核心内容（必会）</p><p><strong>1.环境管理体系标准分类（重要）</strong></p><table><tbody><tr style="text-align:left;"><td rowspan="3"> 按体系标准<span class="font-jcysxh">性质</span>分类<br><br><br><br><span class="font-jcysxh">【口诀】“机关术”</span></td><td><span class="font-jcysxh">基础标准（术语标准）</span>：界定了环境管理有关<span class="font-jcysxh">概念</span>，为理解、应用环境管<br> 理体系标准提供了<span class="font-jcysxh">清晰的定义解释</span></td></tr><tr style="text-align:left;"><td> 管理标准：组织<span class="font-jcysxh">管理行为的规范标准，涵盖环境管理规范、原则及可执行<br> 的准则</span>内容，形成环境<span class="font-jcysxh">管理</span>的<span class="font-jcysxh">标准化文件</span></td></tr><tr style="text-align:left;"><td><span class="font-jcysxh">技术标准</span>：环境管理的<span class="font-jcysxh">技术方法标准</span>，是针对环境变化进行<span class="font-jcysxh">诊断、审核、<br> 评价</span>等规范性<span class="font-jcysxh">方法文件</span></td></tr><tr style="text-align:left;"><td rowspan="2"> 按体系标准<span class="font-jcysxh">功能</span>分类 </td><td><span class="font-jcysxh">组织评价标准</span>：主要针对<span class="font-jcysxh">各部门、车间</span>进行的环境管理评价 </td></tr><tr style="text-align:left;"><td><span class="font-jcysxh">产品评价标准</span>：重点评估<span class="font-jcysxh">产品在原材料购买、生产、使用、废弃等全生命<br> 周期</span>的环境影响 </td></tr></tbody></table><p>2.环境管理体系的基本理念和核心内容（必会）</p><table><tbody><tr><td>环境管理体系的基本理念</td><td>环境管理体系的核心内容（<span class="font-jcysxh">PDCA</span>）</td></tr><tr style="text-align:left;"><td>（1）<span class="font-jcysxh">持续改进</span>：提高环境绩效</td><td>（1）组织所处环境</td></tr><tr style="text-align:left;"><td>（2）法律合规：遵守环境法律、法规和其他要求</td><td>（2）领导作用</td></tr><tr style="text-align:left;"><td>（3）<span class="font-jcysxh">风险管理</span>：制定措施和应急响应计划，降低风险</td><td>（3）策划（P）</td></tr><tr style="text-align:left;"><td>（4）<span class="font-jcysxh">绩效评估</span>：定目标和指标，定期审查</td><td>（4）支持（D）</td></tr><tr style="text-align:left;"><td>（5）<span class="font-jcysxh">沟通与参与</span>：信息共享、意见收集和合作</td><td>（5）运行（D）</td></tr><tr style="text-align:left;"><td>（6）<span class="font-jcysxh">资源管理</span>：降低环境影响并提高资源效率</td><td>（6）绩效评价（C）</td></tr><tr style="text-align:left;"><td> （7）<span class="font-jcysxh">培训和意识</span>：提高员工对环境问题的认识，使之积<br> 极参与环境管理活动 </td><td>（7）改进（A）</td></tr></tbody></table><p><span class="font-jcys">【注】环境管理体系的基本理念与质量管理原则区分。</span></p><div class="font-jc"> 【课中知识拓展】 <p>（1）组织所处环境包括：①理解组织及其所处的环境；②理解相关方的需求和期望；③确定环境管理体系的范围；④环境管理体系。</p><p>（2）领导作用包括：①领导作用和承诺；②环境方针；③组织的角色、职责和权限。</p><p>（3）策划包括：①应对风险和机遇的措施；②环境目标及其实现的策划。</p><p>（4）支持包括：①资源；②能力；③意识；④信息交流；⑤文件化信息。</p><p>（5）运行包括：①运行策划和控制；②应急准备和响应。</p><p>（6）绩效评价包括：①监视、测量、分析和评价；②内部审核；③管理评审。</p><p>（7）改进包括：①总则；②不符合和纠正措施；③持续改进。</p></div><p><strong>【考点总结】</strong></p><p><img src="https://tupian-d290.obs.cn-east-3.myhuaweicloud.com/img/1762610767036.png" alt="" loading="lazy"></p><h3 id="_2-1-3-职业健康安全管理体系" tabindex="-1">2.1.3 职业健康安全管理体系 <a class="header-anchor" href="#_2-1-3-职业健康安全管理体系" aria-label="Permalink to &quot;2.1.3 职业健康安全管理体系&quot;">​</a></h3><p>【考点】职业健康安全管理体系</p><p>【考点概括】</p><p>1.职业健康安全管理体系标准的特点（了解）</p><p>2.职业健康安全管理体系标准要素及应用要求（必会）</p><p>1.职业健康安全管理体系标准的特点（了解）</p><table tabindex="0"><thead><tr><th style="text-align:left;">（1）<span class="font-jcysxh">系统化</span>管理机制</th><th style="text-align:left;">①组织职责系统化；②风险管控系统化；③管理过程系统化</th></tr></thead><tbody><tr><td style="text-align:left;">（2）<span class="font-jcysxh">法制化和规范化</span>管理手段</td><td style="text-align:left;">始终强调法律法规要求和其他要求</td></tr><tr><td style="text-align:left;">（3）<span class="font-jcysxh">广泛</span>的适用性</td><td style="text-align:left;">适用于<span class="font-jcysxh">任何</span>规模、类型和活动的<span class="font-jcysxh">组织 </span></td></tr><tr><td style="text-align:left;">（4）遵循<span class="font-jcysxh">自愿</span>原则</td><td style="text-align:left;"><span class="font-jcysxh">是否建立和保持</span>职业健康安全管理体系，<span class="font-jcysxh">是否</span>进行职业健康安全管 <br>理<span class="font-jcysxh">体系认证审核</span>都取决于组织自身的意愿</td></tr><tr><td style="text-align:left;">（5）与其他管理体系<span class="font-jcysxh">兼容</span></td><td style="text-align:left;">可与质量管理体系、环境管理体系等兼容或整合，方便使用者实施<br>多个管理体系标准</td></tr><tr><td style="text-align:left;">（6）应用的<span class="font-jcysxh">灵活性</span></td><td style="text-align:left;">只对方针、目标和管理体系要素做出要求，既不规定具体的绩效准<br>则，也不提供安全管理体系的设计规范</td></tr><tr><td style="text-align:left;">（7）强调<span class="font-jcysxh">预防为主和持续改进</span></td><td style="text-align:left;">消除危险源和降低职业健康安全风险；<br>持续改进安全管理体系的适宜性、充分性与有效性</td></tr></tbody></table><p><strong>2.职业健康安全管理体系标准要素及应用要求（必会）</strong></p>',51)])])}const x=s(l,[["render",e]]);export{i as __pageData,x as default};
